def is_nested(string):
    # A valid nested subsequence needs two '[' that can be matched with two ']'
    # where the second pair is nested inside the first.
    # Equivalent: there exist i<j<k<l with s[i]='[', s[j]='[', s[k]=']', s[l]=']'.
    state = 0
    for ch in string:
        if state == 0 and ch == '[':
            state = 1
        elif state == 1 and ch == '[':
            state = 2
        elif state == 2 and ch == ']':
            state = 3
        elif state == 3 and ch == ']':
            return True
    return False
